  INSERT INTO public.lampas_confessional_questions
    (document_id, number, number_label, question, answer, doctrine_tags, bible_references, sort_order, metadata)
  VALUES
    (v_doc_id, 1, '1', 'Qual é o fim principal do homem?', 'O fim principal do homem é glorificar a Deus e gozar d''Ele para sempre.', ARRAY['glorificação','propósito humano','criação'], ARRAY['1 Coríntios 10.31','Salmo 73.25-28'], 1, '{"full_seed":true}'::jsonb),
    (v_doc_id, 2, '2', 'Que regra Deus nos deu para nos dirigir no modo de O glorificar e gozar?', 'A Palavra de Deus, contida nas Escrituras do Antigo e Novo Testamento, é a única regra para nos dirigir no modo de O glorificar e gozar.', ARRAY['Escrituras','regra de fé','Palavra de Deus'], ARRAY['2 Timóteo 3.16','Isaías 8.20'], 2, '{"full_seed":true}'::jsonb),
    (v_doc_id, 3, '3', 'O que ensinam principalmente as Escrituras?', 'As Escrituras ensinam principalmente o que o homem deve crer acerca de Deus e que deveres Deus exige do homem.', ARRAY['Escrituras','fé','obediência'], ARRAY['2 Timóteo 1.13','Eclesiastes 12.13'], 3, '{"full_seed":true}'::jsonb),
    (v_doc_id, 4, '4', 'O que é Deus?', 'Deus é Espírito, infinito, eterno e imutável no ser, sabedoria, poder, santidade, justiça, bondade e verdade.', ARRAY['atributos divinos','Deus','ontologia'], ARRAY['João 4.24','Êxodo 3.14','Salmo 147.5'], 4, '{"full_seed":true}'::jsonb),
    (v_doc_id, 5, '5', 'Há mais de um Deus?', 'Há somente um Deus, vivo e verdadeiro.', ARRAY['monoteísmo','Deus'], ARRAY['Deuteronômio 6.4','Jeremias 10.10'], 5, '{"full_seed":true}'::jsonb),
    (v_doc_id, 6, '6', 'Quantas pessoas há na Divindade?', 'Na Divindade há três pessoas: o Pai, o Filho e o Espírito Santo; e estas três são um único Deus, iguais em poder e glória.', ARRAY['Trindade','pessoas divinas','Pai','Filho','Espírito Santo'], ARRAY['Mateus 28.19','2 Coríntios 13.14'], 6, '{"full_seed":true}'::jsonb),
    (v_doc_id, 7, '7', 'Quais são os decretos de Deus?', 'Os decretos de Deus são o seu propósito eterno, segundo o conselho da sua vontade, pelo qual predestinou, para a sua própria glória, tudo o que acontece.', ARRAY['decretos divinos','predestinação','soberania'], ARRAY['Efésios 1.11','Romanos 11.33'], 7, '{"full_seed":true}'::jsonb),
    (v_doc_id, 8, '8', 'Como Deus executa os seus decretos?', 'Deus executa os seus decretos nas obras de criação e de providência.', ARRAY['criação','providência','decretos divinos'], ARRAY['Apocalipse 4.11','Daniel 4.35'], 8, '{"full_seed":true}'::jsonb),
    (v_doc_id, 9, '9', 'Qual é a obra da criação?', 'A obra da criação é o ato de Deus, pelo qual, no princípio, para a manifestação da glória de seu poder, sabedoria e bondade, fez do nada, em seis dias, o mundo e todas as coisas nele contidas.', ARRAY['criação','criação do nada','poder de Deus'], ARRAY['Gênesis 1.1','Hebreus 11.3'], 9, '{"full_seed":true}'::jsonb),
    (v_doc_id, 10, '10', 'Como criou Deus o homem?', 'Deus criou o homem, macho e fêmea, conforme a sua imagem, com conhecimento, justiça e santidade; e com domínio sobre as outras criaturas.', ARRAY['imago Dei','criação do homem','justiça original'], ARRAY['Gênesis 1.26-27','Colossenses 3.10','Efésios 4.24'], 10, '{"full_seed":true}'::jsonb),
    (v_doc_id, 11, '11', 'Quais são as obras da providência de Deus?', 'As obras da providência de Deus são os seus atos santíssimos, sábios e poderosos de conservação e governo de todas as suas criaturas e de todos os seus atos.', ARRAY['providência','governo divino','soberania'], ARRAY['Salmo 145.17','Hebreus 1.3'], 11, '{"full_seed":true}'::jsonb),
    (v_doc_id, 12, '12', 'Que ato especial de providência exerceu Deus para com o homem, no estado em que ele foi criado?', 'Quando Deus criou o homem, entrou com ele numa aliança de obras, prometendo-lhe a vida mediante perfeita obediência, proibindo-lhe, sob pena de morte, de comer do fruto da árvore do conhecimento do bem e do mal.', ARRAY['aliança de obras','criação','obediência'], ARRAY['Gálatas 3.12','Gênesis 2.17'], 12, '{"full_seed":true}'::jsonb),
    (v_doc_id, 13, '13', 'Permaneceu nosso primeiro pai no estado em que ele foi criado?', 'Nossos primeiros pais, tendo livre-arbítrio, decaíram do estado em que foram criados, pecando contra Deus.', ARRAY['queda','livre-arbítrio','pecado original'], ARRAY['Gênesis 3.6-8','Eclesiastes 7.29'], 13, '{"full_seed":true}'::jsonb),
    (v_doc_id, 14, '14', 'O que é o pecado?', 'O pecado é qualquer falta de conformidade à lei de Deus, ou transgressão da mesma.', ARRAY['pecado','lei','transgressão'], ARRAY['1 João 3.4'], 14, '{"full_seed":true}'::jsonb),
    (v_doc_id, 15, '15', 'Em que estado caiu o homem pela sua queda?', 'O homem caiu, por sua queda, num estado de pecado e miséria.', ARRAY['queda','estado de pecado','miséria'], ARRAY['Romanos 5.12'], 15, '{"full_seed":true}'::jsonb),
    (v_doc_id, 16, '16', 'Como veio toda a humanidade a cair em Adão no seu primeiro pecado?', 'O pacto foi feito com Adão, não somente para ele, mas também para a sua posteridade; assim todos os homens, descendentes dele por geração natural, pecaram nele e caíram com ele no seu primeiro pecado.', ARRAY['pecado original','Adão','aliança','imputação'], ARRAY['Romanos 5.12','1 Coríntios 15.22'], 16, '{"full_seed":true}'::jsonb),
    (v_doc_id, 17, '17', 'Em que miséria caiu o homem por sua queda?', 'Por sua queda, o homem caiu na perda da comunhão com Deus, na ira e maldição de Deus e nas misérias desta vida, na morte e nos tormentos do inferno para sempre.', ARRAY['queda','ira de Deus','morte','condenação'], ARRAY['Gênesis 3.8','Romanos 3.16-17','Mateus 25.41'], 17, '{"full_seed":true}'::jsonb),
    (v_doc_id, 18, '18', 'Em que consiste a pecaminosidade do estado em que o homem caiu?', 'A pecaminosidade do estado em que o homem caiu consiste no pecado original que compreende a culpa do primeiro pecado de Adão, a falta de justiça original, bem como a corrupção de toda a sua natureza, chamada pecado original, juntamente com todos os pecados reais que dele procedem.', ARRAY['pecado original','corrupção total','culpa','depravação'], ARRAY['Romanos 5.12','Romanos 3.10-12','Tiago 1.14-15'], 18, '{"full_seed":true}'::jsonb),
    (v_doc_id, 19, '19', 'Em que consiste a miséria do estado em que o homem caiu?', 'Toda a humanidade, pela sua queda, perdeu a comunhão com Deus, está debaixo da sua ira e maldição, e está assim sujeita a todas as misérias desta vida, à morte mesmo, e às penas do inferno para sempre.', ARRAY['queda','miséria humana','condenação','ira de Deus'], ARRAY['Efésios 2.1-3','Gálatas 3.10'], 19, '{"full_seed":true}'::jsonb),
    (v_doc_id, 20, '20', 'Deixou Deus todo gênero humano perecer no estado de pecado e miséria?', 'Agradou a Deus, por sua simples boa vontade, eleger alguns para a vida eterna, e entrar com eles numa aliança de graça, para os libertar do estado de pecado e miséria e introduzi-los num estado de salvação, por meio de um Redentor.', ARRAY['eleição','aliança de graça','soteriologia'], ARRAY['Efésios 1.4-5','Romanos 3.20-22'], 20, '{"full_seed":true}'::jsonb),
    (v_doc_id, 21, '21', 'Quem é o Redentor dos eleitos?', 'O único Redentor dos eleitos é o Senhor Jesus Cristo, que, sendo o eterno Filho de Deus, fez-se homem, e assim foi e continua a ser Deus e homem em duas naturezas distintas e em uma só pessoa, para sempre.', ARRAY['redenção','Encarnação','duas naturezas','pessoa de Cristo'], ARRAY['1 Timóteo 2.5','João 1.14'], 21, '{"full_seed":true}'::jsonb),
    (v_doc_id, 22, '22', 'Como se fez Cristo o Filho de Deus em homem?', 'Cristo, Filho de Deus, se fez homem, tomando um corpo real e uma alma racional, sendo concebido pelo poder do Espírito Santo no ventre da Virgem Maria e nascendo dela, sem contudo haver pecado.', ARRAY['Encarnação','virgem Maria','impecabilidade','Espírito Santo'], ARRAY['Lucas 1.31-35','Colossenses 2.9','Hebreus 4.15'], 22, '{"full_seed":true}'::jsonb),
    (v_doc_id, 23, '23', 'Que ofícios exerce Cristo como nosso Redentor?', 'Cristo, como nosso Redentor, exerce os ofícios de profeta, de sacerdote e de rei, tanto na sua humilhação como na sua exaltação.', ARRAY['tríplice ofício','profeta','sacerdote','rei'], ARRAY['Atos 3.22','Hebreus 5.6','Salmo 2.6'], 23, '{"full_seed":true}'::jsonb),
    (v_doc_id, 24, '24', 'Como exerce Cristo o ofício de profeta?', 'Cristo exerce o ofício de profeta, revelando-nos, pela sua Palavra e Espírito, a vontade de Deus para nossa salvação.', ARRAY['profeta','revelação','Palavra de Deus'], ARRAY['João 15.15','1 Pedro 1.10-12'], 24, '{"full_seed":true}'::jsonb),
    (v_doc_id, 25, '25', 'Como exerce Cristo o ofício de sacerdote?', 'Cristo exerce o ofício de sacerdote, oferecendo-se uma única vez a si mesmo em sacrifício para satisfazer a justiça divina e nos reconciliar com Deus, e intercedendo continuamente por nós.', ARRAY['sacerdócio','expiação','intercessão','sacrifício'], ARRAY['Hebreus 9.14-15','Hebreus 7.25'], 25, '{"full_seed":true}'::jsonb),
    (v_doc_id, 26, '26', 'Como exerce Cristo o ofício de rei?', 'Cristo exerce o ofício de rei, dominando-nos e defendendo-nos, contendo e conquistando todos os seus e nossos inimigos.', ARRAY['reino de Cristo','realeza','governo'], ARRAY['Isaías 33.22','1 Coríntios 15.25'], 26, '{"full_seed":true}'::jsonb),
    (v_doc_id, 27, '27', 'Em que consiste a humilhação de Cristo?', 'A humilhação de Cristo consiste em ter ele nascido, e isso em posição humilde, ter-se submetido à lei, em ter sofrido as misérias desta vida, a ira de Deus e a morte maldita da cruz, em ter sido sepultado e em ter permanecido debaixo do poder da morte por algum tempo.', ARRAY['humilhação de Cristo','Encarnação','morte de Cristo','expiação'], ARRAY['Filipenses 2.6-8','Gálatas 4.4','1 Coríntios 15.3-4'], 27, '{"full_seed":true}'::jsonb),
    (v_doc_id, 28, '28', 'Em que consiste a exaltação de Cristo?', 'A exaltação de Cristo consiste em ter ressuscitado ao terceiro dia de entre os mortos, em ter subido ao céu, em estar assentado à destra de Deus Pai e em vir julgar o mundo no último dia.', ARRAY['exaltação de Cristo','ressurreição','ascensão','segunda vinda'], ARRAY['1 Coríntios 15.4','Efésios 1.20','Atos 1.11'], 28, '{"full_seed":true}'::jsonb),
    (v_doc_id, 29, '29', 'Como nos tornamos participantes da redenção comprada por Cristo?', 'Nos tornamos participantes da redenção comprada por Cristo pela aplicação eficaz da mesma a nós pelo seu Espírito Santo.', ARRAY['aplicação da redenção','Espírito Santo','soteriologia'], ARRAY['João 1.11-12','João 3.5-6'], 29, '{"full_seed":true}'::jsonb),
    (v_doc_id, 30, '30', 'Como o Espírito aplica a nós a redenção comprada por Cristo?', 'O Espírito aplica a nós a redenção comprada por Cristo, gerando em nós a fé, por cujo meio nos une a Cristo em nossa vocação eficaz.', ARRAY['Espírito Santo','fé','vocação eficaz','união com Cristo'], ARRAY['Efésios 2.8','Efésios 1.13-14'], 30, '{"full_seed":true}'::jsonb),
    (v_doc_id, 31, '31', 'O que é vocação eficaz?', 'A vocação eficaz é a obra do Espírito de Deus, pela qual, convencendo-nos do nosso pecado e miséria, iluminando o nosso entendimento no conhecimento de Cristo, renovando a nossa vontade, nos persuade e nos habilita a abraçar Jesus Cristo, a ele livremente oferecido no Evangelho.', ARRAY['vocação eficaz','regeneração','Espírito Santo','convicção de pecado'], ARRAY['2 Timóteo 1.9','2 Tessalonicenses 2.13-14'], 31, '{"full_seed":true}'::jsonb),
    (v_doc_id, 32, '32', 'Quais são os benefícios que nesta vida acompanham ou decorrem da vocação eficaz?', 'Os benefícios que nesta vida acompanham ou decorrem da vocação eficaz são: a justificação, a adoção e a santificação e os demais benefícios que nesta vida os acompanham ou decorrem.', ARRAY['vocação eficaz','justificação','adoção','santificação'], ARRAY['Romanos 8.30'], 32, '{"full_seed":true}'::jsonb),
    (v_doc_id, 33, '33', 'O que é justificação?', 'Justificação é o ato da livre graça de Deus, pelo qual ele perdoa todos os nossos pecados e nos aceita como justos diante dele, somente pela justiça de Cristo imputada a nós e recebida somente pela fé.', ARRAY['justificação','imputação','fé','graça'], ARRAY['Romanos 3.24','Romanos 4.6-8','2 Coríntios 5.21'], 33, '{"full_seed":true}'::jsonb),
    (v_doc_id, 34, '34', 'O que é adoção?', 'Adoção é um ato da livre graça de Deus, pelo qual somos recebidos no número e temos direito a todos os privilégios dos filhos de Deus.', ARRAY['adoção','filiação divina','graça'], ARRAY['João 1.12','Romanos 8.17'], 34, '{"full_seed":true}'::jsonb),
    (v_doc_id, 35, '35', 'O que é santificação?', 'Santificação é a obra da livre graça de Deus pela qual somos renovados em todo o nosso ser segundo a imagem de Deus e habilitados cada vez mais a morrer para o pecado e a viver para a justiça.', ARRAY['santificação','renovação','imagem de Deus','vida cristã'], ARRAY['2 Tessalonicenses 2.13','Efésios 4.23-24','Romanos 6.4'], 35, '{"full_seed":true}'::jsonb),
    (v_doc_id, 36, '36', 'Quais são os benefícios que nesta vida acompanham ou decorrem da justificação, adoção e santificação?', 'Os benefícios que nesta vida acompanham ou decorrem da justificação, adoção e santificação são: a certeza do amor de Deus, a paz de consciência, a alegria no Espírito Santo, o crescimento na graça e a perseverança nela até o fim.', ARRAY['asseguração','paz','alegria','perseverança'], ARRAY['Romanos 5.1-2','Romanos 14.17'], 36, '{"full_seed":true}'::jsonb),
    (v_doc_id, 37, '37', 'Que benefícios recebem os crentes de Cristo, na morte?', 'Na morte, as almas dos crentes são tornadas perfeitas em santidade e passam imediatamente para a glória; e os seus corpos, ainda unidos a Cristo, repousam em seus túmulos até a ressurreição.', ARRAY['morte dos crentes','santificação consumada','imortalidade'], ARRAY['Hebreus 12.23','Filipenses 1.23','1 Tessalonicenses 4.14'], 37, '{"full_seed":true}'::jsonb),
    (v_doc_id, 38, '38', 'Que benefícios recebem os crentes de Cristo, na ressurreição?', 'Na ressurreição, os crentes são levantados com glória, abertamente reconhecidos e absolvidos no dia do juízo, e tornados perfeitamente bem-aventurados no pleno gozo de Deus para sempre.', ARRAY['ressurreição','glorificação','julgamento final','beatitude'], ARRAY['1 Coríntios 15.42-43','Mateus 25.33-34'], 38, '{"full_seed":true}'::jsonb),
    (v_doc_id, 39, '39', 'Qual é o dever que Deus exige do homem?', 'O dever que Deus exige do homem é obediência à sua vontade revelada.', ARRAY['lei','obediência','dever'], ARRAY['Eclesiastes 12.13','Miquéias 6.8'], 39, '{"full_seed":true}'::jsonb),
    (v_doc_id, 40, '40', 'Que regra Deus primeiramente revelou ao homem para o seu dever?', 'A regra que Deus primeiramente revelou ao homem para o seu dever foi a lei moral.', ARRAY['lei moral','lei natural','revelação'], ARRAY['Romanos 2.14-15','Romanos 10.5'], 40, '{"full_seed":true}'::jsonb),
    (v_doc_id, 41, '41', 'Onde está resumida a lei moral?', 'A lei moral está resumida nos Dez Mandamentos.', ARRAY['Dez Mandamentos','lei moral'], ARRAY['Deuteronômio 10.4','Mateus 19.17'], 41, '{"full_seed":true}'::jsonb),
    (v_doc_id, 42, '42', 'Qual é a súmula dos Dez Mandamentos?', 'A súmula dos Dez Mandamentos é: amarás ao Senhor teu Deus, de todo teu coração, de toda a tua alma, de todas as tuas forças e de todo o teu entendimento; e ao teu próximo como a ti mesmo.', ARRAY['amor a Deus','amor ao próximo','grande mandamento'], ARRAY['Mateus 22.37-40'], 42, '{"full_seed":true}'::jsonb),
    (v_doc_id, 43, '43', 'Qual é o prefácio dos Dez Mandamentos?', 'O prefácio dos Dez Mandamentos é: "Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da servidão."', ARRAY['Dez Mandamentos','redenção','autoridade divina'], ARRAY['Êxodo 20.2'], 43, '{"full_seed":true}'::jsonb),
    (v_doc_id, 44, '44', 'Que nos ensina o prefácio dos Dez Mandamentos?', 'O prefácio dos Dez Mandamentos ensina-nos que, por ser ele o Senhor e nosso Deus e Redentor, somos obrigados a guardar todos os seus mandamentos.', ARRAY['obrigação moral','redenção','lei'], ARRAY['Êxodo 20.2','Lucas 1.74-75'], 44, '{"full_seed":true}'::jsonb),
    (v_doc_id, 45, '45', 'Qual é o primeiro mandamento?', 'O primeiro mandamento é: "Não terás outros deuses diante de mim."', ARRAY['1º mandamento','adoração exclusiva','monoteísmo'], ARRAY['Êxodo 20.3'], 45, '{"full_seed":true}'::jsonb),
    (v_doc_id, 46, '46', 'O que se ordena no primeiro mandamento?', 'No primeiro mandamento se ordena que conheçamos e reconheçamos a Deus como o único Deus verdadeiro e nosso Deus, e que o adoremos e glorifiquemos como convém.', ARRAY['1º mandamento','adoração','conhecimento de Deus'], ARRAY['1 Crônicas 28.9','Deuteronômio 26.17'], 46, '{"full_seed":true}'::jsonb),
    (v_doc_id, 47, '47', 'O que se proíbe no primeiro mandamento?', 'No primeiro mandamento se proíbe o ateísmo, a idolatria e negar ou não adorar e glorificar o único Deus verdadeiro como Deus e nosso Deus.', ARRAY['1º mandamento','ateísmo','idolatria'], ARRAY['Salmo 14.1','Romanos 1.20-21'], 47, '{"full_seed":true}'::jsonb),
    (v_doc_id, 48, '48', 'Que nos ensinam as palavras "diante de mim" no primeiro mandamento?', 'As palavras "diante de mim" no primeiro mandamento nos ensinam que Deus, que tudo vê, nota e se ofende muito com o pecado de ter outros deuses.', ARRAY['1º mandamento','onisciência','idolatria'], ARRAY['Ezequiel 8.5-6'], 48, '{"full_seed":true}'::jsonb),
    (v_doc_id, 49, '49', 'Qual é o segundo mandamento?', 'O segundo mandamento é: "Não farás para ti imagem de escultura, nem semelhança alguma do que há em cima nos céus, nem em baixo na terra, nem nas águas debaixo da terra; não te inclinarás a elas nem as servirás, porque eu, o Senhor teu Deus, sou Deus zeloso, que visito a iniquidade dos pais nos filhos até a terceira e quarta geração dos que me aborrecem, e uso de misericórdia até mil gerações com os que me amam e guardam os meus mandamentos."', ARRAY['2º mandamento','imagens','adoração regulada'], ARRAY['Êxodo 20.4-6'], 49, '{"full_seed":true}'::jsonb),
    (v_doc_id, 50, '50', 'O que se ordena no segundo mandamento?', 'No segundo mandamento se ordena o recebimento e a observância de toda a adoração religiosa e de todas as ordenanças que Deus instituiu em sua Palavra.', ARRAY['2º mandamento','princípio regulador','adoração'], ARRAY['Deuteronômio 12.32','Mateus 28.20'], 50, '{"full_seed":true}'::jsonb),
    (v_doc_id, 51, '51', 'O que se proíbe no segundo mandamento?', 'No segundo mandamento se proíbe adorar a Deus por meio de imagens ou por qualquer outra forma não prescrita na Palavra de Deus.', ARRAY['2º mandamento','idolatria','princípio regulador'], ARRAY['Deuteronômio 4.15-16','Êxodo 32.8'], 51, '{"full_seed":true}'::jsonb),
    (v_doc_id, 52, '52', 'Quais são os motivos apresentados para o cumprimento do segundo mandamento?', 'Os motivos apresentados para o cumprimento do segundo mandamento são o domínio soberano de Deus sobre nós, a sua propriedade sobre nós e o zelo da sua honra, porquanto ele é Deus zeloso.', ARRAY['2º mandamento','soberania','zelo de Deus'], ARRAY['Salmo 45.11','Êxodo 34.13-14'], 52, '{"full_seed":true}'::jsonb),
    (v_doc_id, 53, '53', 'Qual é o terceiro mandamento?', 'O terceiro mandamento é: "Não tomarás o nome do Senhor teu Deus em vão, porque o Senhor não terá por inocente o que tomar o seu nome em vão."', ARRAY['3º mandamento','nome de Deus','blasfêmia'], ARRAY['Êxodo 20.7'], 53, '{"full_seed":true}'::jsonb),
    (v_doc_id, 54, '54', 'O que se ordena no terceiro mandamento?', 'No terceiro mandamento se ordena o uso santo e reverente do nome de Deus, dos títulos, atributos, ordenanças, Palavra e obras de Deus.', ARRAY['3º mandamento','reverência','nome de Deus'], ARRAY['Mateus 6.9','Salmo 29.2'], 54, '{"full_seed":true}'::jsonb),
    (v_doc_id, 55, '55', 'O que se proíbe no terceiro mandamento?', 'No terceiro mandamento se proíbe todo o profanamento e abuso do nome de Deus, dos títulos, atributos, ordenanças, Palavra e obras de Deus.', ARRAY['3º mandamento','profanação','blasfêmia'], ARRAY['Malaquias 1.6-7','Malaquias 2.2'], 55, '{"full_seed":true}'::jsonb),
    (v_doc_id, 56, '56', 'Qual é a razão apresentada para o cumprimento do terceiro mandamento?', 'A razão apresentada para o cumprimento do terceiro mandamento é que, por mais que fiquem impunes os que transgridem esse mandamento perante os homens, o Senhor nosso Deus não os terá por inocentes.', ARRAY['3º mandamento','julgamento divino','impunidade'], ARRAY['1 Samuel 2.12','1 Samuel 2.17'], 56, '{"full_seed":true}'::jsonb),
    (v_doc_id, 57, '57', 'Qual é o quarto mandamento?', 'O quarto mandamento é: "Lembra-te do dia do sábado para santificá-lo. Seis dias trabalharás e farás toda a tua obra; mas o sétimo é o sábado do Senhor teu Deus; não farás nenhum trabalho nele, nem tu, nem o teu filho, nem a tua filha, nem o teu servo, nem a tua serva, nem o teu animal, nem o teu estrangeiro que está dentro das tuas portas; porque em seis dias o Senhor fez os céus e a terra, o mar e tudo o que neles há, e ao sétimo dia descansou; por isso o Senhor abençoou o dia do sábado e o santificou."', ARRAY['4º mandamento','sábado','descanso'], ARRAY['Êxodo 20.8-11'], 57, '{"full_seed":true}'::jsonb),
    (v_doc_id, 58, '58', 'O que se ordena no quarto mandamento?', 'No quarto mandamento se ordena a santificação dos tempos que Deus designou para o seu culto, especialmente um dia de sete, o sábado do Senhor, a ser santificado por ele como o dia de descanso sagrado durante toda a vida.', ARRAY['4º mandamento','sábado','culto','descanso'], ARRAY['Levítico 19.30','Isaías 56.2'], 58, '{"full_seed":true}'::jsonb),
    (v_doc_id, 59, '59', 'Qual dos sete dias Deus designou para o sábado?', 'Desde a criação do mundo, Deus designou o sétimo dia para ser sábado; foi mudado para o primeiro dia da semana por Cristo e assim continuou até ao fim do mundo, sendo o sábado cristão.', ARRAY['4º mandamento','Dia do Senhor','ressurreição'], ARRAY['Gênesis 2.2-3','João 20.19'], 59, '{"full_seed":true}'::jsonb),
    (v_doc_id, 60, '60', 'Como se deve santificar o sábado?', 'O sábado se deve santificar com um descanso sagrado durante todo o dia até das obras e recreações que são lícitas nos outros dias, e com o emprego de todo o tempo no exercício público e privado do culto de Deus, exceto o que é necessário para as obras de necessidade e misericórdia.', ARRAY['4º mandamento','sábado','culto','descanso'], ARRAY['Isaías 58.13','Mateus 12.11-12'], 60, '{"full_seed":true}'::jsonb),
    (v_doc_id, 61, '61', 'Qual é o quinto mandamento?', 'O quinto mandamento é: "Honra a teu pai e a tua mãe, para que se prolonguem os teus dias na terra que o Senhor teu Deus te dá."', ARRAY['5º mandamento','autoridade','família'], ARRAY['Êxodo 20.12'], 61, '{"full_seed":true}'::jsonb),
    (v_doc_id, 62, '62', 'O que se ordena no quinto mandamento?', 'No quinto mandamento se ordena que preservemos a honra e cumpramos os deveres que nos competem nos diferentes graus de relação que temos, seja de superior, de inferior ou de igual.', ARRAY['5º mandamento','autoridade','honra','relações sociais'], ARRAY['Romanos 13.1','Efésios 5.21-22','Efésios 6.1'], 62, '{"full_seed":true}'::jsonb),
    (v_doc_id, 63, '63', 'O que se proíbe no quinto mandamento?', 'No quinto mandamento se proíbe negligenciar ou fazer qualquer coisa que seja contra a honra e o dever pertencentes a cada um nos seus diferentes graus de relação.', ARRAY['5º mandamento','desonra','autoridade'], ARRAY['Mateus 15.4-6','Ezequiel 34.2-4'], 63, '{"full_seed":true}'::jsonb),
    (v_doc_id, 64, '64', 'Qual é a razão apresentada para o cumprimento do quinto mandamento?', 'A razão apresentada para o cumprimento do quinto mandamento é uma promessa de longa vida e de prosperidade especialmente para os que honram a seus pais.', ARRAY['5º mandamento','promessa','bênção'], ARRAY['Deuteronômio 5.16','Efésios 6.2-3'], 64, '{"full_seed":true}'::jsonb),
    (v_doc_id, 65, '65', 'Qual é o sexto mandamento?', 'O sexto mandamento é: "Não matarás."', ARRAY['6º mandamento','vida humana'], ARRAY['Êxodo 20.13'], 65, '{"full_seed":true}'::jsonb),
    (v_doc_id, 66, '66', 'O que se ordena no sexto mandamento?', 'No sexto mandamento se ordena todas as diligências legítimas para preservar a nossa própria vida e a de nosso próximo.', ARRAY['6º mandamento','preservação da vida','próximo'], ARRAY['Efésios 5.29','1 Reis 18.4'], 66, '{"full_seed":true}'::jsonb),
    (v_doc_id, 67, '67', 'O que se proíbe no sexto mandamento?', 'No sexto mandamento se proíbe o tirar injustamente a nossa própria vida ou a de nosso próximo, ou qualquer coisa que conduz para isso.', ARRAY['6º mandamento','homicídio','violência'], ARRAY['Atos 16.28','Gênesis 9.6'], 67, '{"full_seed":true}'::jsonb),
    (v_doc_id, 68, '68', 'Qual é o sétimo mandamento?', 'O sétimo mandamento é: "Não adulterarás."', ARRAY['7º mandamento','pureza','matrimônio'], ARRAY['Êxodo 20.14'], 68, '{"full_seed":true}'::jsonb),
    (v_doc_id, 69, '69', 'O que se ordena no sétimo mandamento?', 'No sétimo mandamento se ordena a preservação da nossa própria castidade e do próximo, no coração, nas palavras e no procedimento.', ARRAY['7º mandamento','castidade','pureza'], ARRAY['1 Coríntios 7.2-3','Colossenses 4.6'], 69, '{"full_seed":true}'::jsonb),
    (v_doc_id, 70, '70', 'O que se proíbe no sétimo mandamento?', 'No sétimo mandamento se proíbe todo o pensamento, palavra e ação impudicos.', ARRAY['7º mandamento','impureza','luxúria'], ARRAY['Mateus 15.19','Efésios 5.3-4'], 70, '{"full_seed":true}'::jsonb),
    (v_doc_id, 71, '71', 'Qual é o oitavo mandamento?', 'O oitavo mandamento é: "Não furtarás."', ARRAY['8º mandamento','propriedade','justiça'], ARRAY['Êxodo 20.15'], 71, '{"full_seed":true}'::jsonb),
    (v_doc_id, 72, '72', 'O que se ordena no oitavo mandamento?', 'No oitavo mandamento se ordena o lícito procurar e fomentar as riquezas e o bem-estar nosso e do próximo.', ARRAY['8º mandamento','propriedade','mordomia'], ARRAY['Levítico 25.35','Deuteronômio 22.1-5'], 72, '{"full_seed":true}'::jsonb),
    (v_doc_id, 73, '73', 'O que se proíbe no oitavo mandamento?', 'No oitavo mandamento se proíbe tudo o que injustamente impeça ou prejudique as riquezas ou bem-estar nosso ou do próximo.', ARRAY['8º mandamento','roubo','injustiça'], ARRAY['1 Tessalonicenses 4.6','Provérbios 11.1'], 73, '{"full_seed":true}'::jsonb),
    (v_doc_id, 74, '74', 'Qual é o nono mandamento?', 'O nono mandamento é: "Não dirás falso testemunho contra o teu próximo."', ARRAY['9º mandamento','verdade','testemunho'], ARRAY['Êxodo 20.16'], 74, '{"full_seed":true}'::jsonb),
    (v_doc_id, 75, '75', 'O que se ordena no nono mandamento?', 'No nono mandamento se ordena manter e promover a verdade entre os homens e a nossa própria boa reputação e a do nosso próximo.', ARRAY['9º mandamento','verdade','honra'], ARRAY['Zacarias 8.16','3 João 1.12'], 75, '{"full_seed":true}'::jsonb),
    (v_doc_id, 76, '76', 'O que se proíbe no nono mandamento?', 'No nono mandamento se proíbe tudo o que prejudica a verdade e a boa reputação nossa e do nosso próximo.', ARRAY['9º mandamento','mentira','difamação'], ARRAY['Salmo 15.3','Provérbios 6.16-19'], 76, '{"full_seed":true}'::jsonb),
    (v_doc_id, 77, '77', 'Qual é o décimo mandamento?', 'O décimo mandamento é: "Não cobiçarás a casa do teu próximo; não cobiçarás a mulher do teu próximo, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma que pertença ao teu próximo."', ARRAY['10º mandamento','cobiça','contentamento'], ARRAY['Êxodo 20.17'], 77, '{"full_seed":true}'::jsonb),
    (v_doc_id, 78, '78', 'O que se ordena no décimo mandamento?', 'No décimo mandamento se ordena o contentamento pleno com a nossa própria condição e uma disposição favorável e caridosa para com o nosso próximo e tudo o que lhe pertence.', ARRAY['10º mandamento','contentamento','amor ao próximo'], ARRAY['Hebreus 13.5','1 Timóteo 6.6'], 78, '{"full_seed":true}'::jsonb),
    (v_doc_id, 79, '79', 'O que se proíbe no décimo mandamento?', 'No décimo mandamento se proíbe todo o descontentamento com a nossa situação, a inveja das prosperidades do próximo e todo desejo e afeição imoderados relativos a tudo o que lhe pertence.', ARRAY['10º mandamento','cobiça','inveja'], ARRAY['1 Coríntios 10.10','Gálatas 5.26'], 79, '{"full_seed":true}'::jsonb),
    (v_doc_id, 80, '80', 'É capaz alguém de observar perfeitamente os mandamentos de Deus?', 'Nenhum ser humano, desde a queda, é capaz, nesta vida, de guardar perfeitamente os mandamentos de Deus, mas diariamente os transgride em pensamento, palavra e ação.', ARRAY['depravação total','imperfeição','queda'], ARRAY['Eclesiastes 7.20','1 João 1.8'], 80, '{"full_seed":true}'::jsonb),
    (v_doc_id, 81, '81', 'São todos os pecados igualmente odiosos?', 'Alguns pecados em si mesmos e por seus efeitos são mais odiosos a Deus do que outros.', ARRAY['pecado','gradação do pecado','gravidade'], ARRAY['João 19.11','Mateus 11.22-24'], 81, '{"full_seed":true}'::jsonb),
    (v_doc_id, 82, '82', 'O que merecem todos os pecados?', 'Todo pecado merece a ira e a maldição de Deus, tanto nesta vida como na que há de vir.', ARRAY['pecado','ira de Deus','condenação'], ARRAY['Efésios 5.6','Gálatas 3.10'], 82, '{"full_seed":true}'::jsonb),
    (v_doc_id, 83, '83', 'O que nos exige Deus para escaparmos da sua ira e maldição merecidas por causa do pecado?', 'Para escaparmos da ira e maldição de Deus merecidas por causa do pecado, Deus nos exige fé em Jesus Cristo, arrependimento para vida e o uso diligente de todos os meios externos da graça.', ARRAY['salvação','fé','arrependimento','meios de graça'], ARRAY['Atos 20.21','Atos 16.30-31'], 83, '{"full_seed":true}'::jsonb),
    (v_doc_id, 84, '84', 'O que é a fé em Jesus Cristo?', 'A fé salvadora em Jesus Cristo é uma graça do Espírito Santo pela qual recebemos e descansamos em Cristo somente para salvação, tal como ele nos é oferecido no Evangelho.', ARRAY['fé salvadora','Espírito Santo','Cristo','soteriologia'], ARRAY['João 1.12','Atos 16.31','Filipenses 3.9'], 84, '{"full_seed":true}'::jsonb),
    (v_doc_id, 85, '85', 'O que é o arrependimento que conduz à vida?', 'O arrependimento que conduz à vida é uma graça do Espírito Santo pela qual o pecador, tendo verdadeiro senso dos seus pecados, e apreendendo a misericórdia de Deus em Cristo, se enluta e odeia os seus pecados, voltando-se deles para Deus com pleno propósito e empenho em nova obediência.', ARRAY['arrependimento','graça','obediência','Espírito Santo'], ARRAY['Atos 11.18','2 Coríntios 7.11'], 85, '{"full_seed":true}'::jsonb),
    (v_doc_id, 86, '86', 'O que são os meios externos e ordinários pelos quais Cristo nos comunica os benefícios da redenção?', 'Os meios externos e ordinários pelos quais Cristo nos comunica os benefícios da redenção são as suas ordenanças, especialmente a Palavra, os sacramentos e a oração; todos os quais são eficazes para a salvação dos eleitos.', ARRAY['meios de graça','Palavra','sacramentos','oração'], ARRAY['Mateus 28.19-20','Atos 2.41-42'], 86, '{"full_seed":true}'::jsonb),
    (v_doc_id, 87, '87', 'Como a Palavra deve ser lida e ouvida para que seja eficaz para a salvação?', 'Para que a Palavra seja eficaz para a salvação, devemos dar-lhe atenção diligente e com fé e reverência; devemos recebê-la com amor como Palavra de Deus; ela deve morar em nós com abundância; e devemos pô-la em prática em nossas vidas.', ARRAY['Palavra de Deus','pregação','meios de graça'], ARRAY['Provérbios 8.34','1 Tessalonicenses 2.13','Colossenses 3.16'], 87, '{"full_seed":true}'::jsonb),
    (v_doc_id, 88, '88', 'Como os sacramentos se tornam meios eficazes de salvação?', 'Os sacramentos se tornam meios eficazes de salvação, não por qualquer virtude que haja neles ou em quem os administra, mas somente pela bênção de Cristo e pela operação do seu Espírito nos que os recebem pela fé.', ARRAY['sacramentos','Espírito Santo','fé','meios de graça'], ARRAY['1 Pedro 3.21','1 Coríntios 3.7'], 88, '{"full_seed":true}'::jsonb),
    (v_doc_id, 89, '89', 'Quais são os sacramentos do Novo Testamento?', 'Os sacramentos do Novo Testamento são o Batismo e a Ceia do Senhor.', ARRAY['sacramentos','Batismo','Ceia do Senhor'], ARRAY['Mateus 28.19','1 Coríntios 11.23'], 89, '{"full_seed":true}'::jsonb),
    (v_doc_id, 90, '90', 'O que é o Batismo?', 'O Batismo é um sacramento no qual a lavagem com água em nome do Pai, do Filho e do Espírito Santo significa e sela nossa inserção na aliança da graça, nossa participação em Cristo e nos benefícios da aliança, e o nosso compromisso com a obrigação de ser do Senhor.', ARRAY['Batismo','aliança','sacramento','regeneração'], ARRAY['Mateus 28.19','Gálatas 3.27','Romanos 6.4'], 90, '{"full_seed":true}'::jsonb),
    (v_doc_id, 91, '91', 'A quem deve ser administrado o Batismo?', 'O Batismo não deve ser administrado a quem não é membro da Igreja visível antes de confessar fé e obediência a Cristo, mas os filhos dos membros da aliança devem ser batizados.', ARRAY['Batismo','aliança','batismo de infantes','Igreja visível'], ARRAY['Atos 8.36-37','Atos 2.38-39','Gênesis 17.7-10'], 91, '{"full_seed":true}'::jsonb),
    (v_doc_id, 92, '92', 'O que é a Ceia do Senhor?', 'A Ceia do Senhor é um sacramento no qual, dando e recebendo pão e vinho segundo a instituição de Cristo, proclama-se sua morte, e os que dignamente a recebem alimentam-se, não de modo carnal e corporal, mas pela fé, de seu corpo e seu sangue, com todos os seus benefícios, para crescimento espiritual e fortalecimento de sua graça.', ARRAY['Ceia do Senhor','sacramento','fé','morte de Cristo'], ARRAY['1 Coríntios 11.23-26','1 Coríntios 10.16'], 92, '{"full_seed":true}'::jsonb),
    (v_doc_id, 93, '93', 'O que é requerido para a digna recepção da Ceia do Senhor?', 'Para a digna recepção da Ceia do Senhor é requerida a auto-prova quanto ao conhecimento para discernir o corpo do Senhor, à fé para se alimentar dele, ao arrependimento, ao amor e à nova obediência; a fim de que não venha a comer e beber sua própria condenação.', ARRAY['Ceia do Senhor','auto-exame','indigno','disciplina'], ARRAY['1 Coríntios 11.28-29'], 93, '{"full_seed":true}'::jsonb),
    (v_doc_id, 94, '94', 'O que é a oração?', 'A oração é oferecer os nossos desejos a Deus em nome de Cristo pelo auxílio do Espírito Santo, confessando os nossos pecados e reconhecendo com gratidão as suas misericórdias.', ARRAY['oração','intercessão','confissão','Espírito Santo'], ARRAY['Filipenses 4.6','1 João 5.14','Romanos 8.26'], 94, '{"full_seed":true}'::jsonb),
    (v_doc_id, 95, '95', 'Por quais coisas devemos orar?', 'Devemos orar por todas as coisas que sirvam para a glória de Deus e para o bem de nós mesmos e dos outros, mas não por coisas ilegítimas.', ARRAY['oração','vontade de Deus','intercessão'], ARRAY['1 João 5.14','João 16.23'], 95, '{"full_seed":true}'::jsonb),
    (v_doc_id, 96, '96', 'Em nome de quem devemos orar?', 'Devemos orar em nome de Cristo somente, e não nos apresentar a Deus senão com a confiança que nos vem da sua mediação.', ARRAY['oração','mediação de Cristo','em nome de Jesus'], ARRAY['João 16.23-24','Hebreus 4.14-16'], 96, '{"full_seed":true}'::jsonb),
    (v_doc_id, 97, '97', 'Como devemos ser guiados no modo de orar?', 'A Palavra de Deus nos guia no modo de orar; e a única regra de oração que Cristo nos deu é a que se acha na Bíblia, a chamada Oração do Senhor.', ARRAY['oração','Oração do Senhor','Palavra de Deus'], ARRAY['1 João 5.14','Lucas 11.1'], 97, '{"full_seed":true}'::jsonb),
    (v_doc_id, 98, '98', 'O que é a Oração do Senhor?', 'A Oração do Senhor é aquela que Cristo ensinou a seus discípulos: "Pai nosso, que estás nos céus, santificado seja o teu nome; venha o teu reino; seja feita a tua vontade, assim na terra como no céu; o pão nosso de cada dia nos dá hoje; e perdoa-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores; e não nos deixes cair em tentação, mas livra-nos do mal; porque teu é o reino, e o poder, e a glória, para sempre. Amém."', ARRAY['Oração do Senhor','oração','modelo'], ARRAY['Mateus 6.9-13','Lucas 11.2-4'], 98, '{"full_seed":true}'::jsonb),
    (v_doc_id, 99, '99', 'O que nos ensina o prefácio da Oração do Senhor?', 'O prefácio da Oração do Senhor ("Pai nosso, que estás nos céus") nos ensina a aproximar-nos de Deus com santa reverência e confiança como filhos para com um pai; e nos deve mover a orar com e por outros.', ARRAY['Oração do Senhor','filiação divina','reverência'], ARRAY['Romanos 8.15','Isaías 63.16'], 99, '{"full_seed":true}'::jsonb),
    (v_doc_id, 100, '100', 'O que pedimos na primeira petição?', 'Na primeira petição, que é "Santificado seja o teu nome", pedimos que Deus nos capacite e outros a glorificá-lo em todas as coisas pelas quais ele se dá a conhecer, e que disponha todas as coisas para a sua própria glória.', ARRAY['Oração do Senhor','santificação','glorificação'], ARRAY['Salmo 67.1-3','Romanos 11.36'], 100, '{"full_seed":true}'::jsonb),
    (v_doc_id, 101, '101', 'O que pedimos na segunda petição?', 'Na segunda petição, que é "Venha o teu reino", pedimos que o reino de Satanás seja destruído e que o reino da graça seja avançado, nós mesmos e outros sendo levados e mantidos nele, e que o reino da glória venha em breve.', ARRAY['Oração do Senhor','reino de Deus','escatologia'], ARRAY['Mateus 6.33','Apocalipse 12.10-11'], 101, '{"full_seed":true}'::jsonb),
    (v_doc_id, 102, '102', 'O que pedimos na terceira petição?', 'Na terceira petição, que é "Seja feita a tua vontade, assim na terra como no céu", pedimos que Deus, por sua graça, nos torne capazes e dispostos a saber, obedecer e submeter-nos em tudo à sua vontade, assim como os anjos o fazem no céu.', ARRAY['Oração do Senhor','vontade de Deus','obediência'], ARRAY['Salmo 103.20-21','Romanos 12.2'], 102, '{"full_seed":true}'::jsonb),
    (v_doc_id, 103, '103', 'O que pedimos na quarta petição?', 'Na quarta petição, que é "O pão nosso de cada dia nos dá hoje", pedimos receber de Deus uma porção conveniente dos bens desta vida e com ela a bênção dele.', ARRAY['Oração do Senhor','providência','necessidades diárias'], ARRAY['Provérbios 30.8-9','1 Timóteo 4.4-5'], 103, '{"full_seed":true}'::jsonb),
    (v_doc_id, 104, '104', 'O que pedimos na quinta petição?', 'Na quinta petição, que é "Perdoa-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores", pedimos a Deus que, por causa de Cristo, nos perdoe todos os nossos pecados, sendo animados a fazê-lo porque a sua graça nos habilita de coração a perdoar aos outros.', ARRAY['Oração do Senhor','perdão','graça'], ARRAY['Salmo 51.1-2','Lucas 11.4'], 104, '{"full_seed":true}'::jsonb),
    (v_doc_id, 105, '105', 'O que pedimos na sexta petição?', 'Na sexta petição, que é "E não nos deixes cair em tentação, mas livra-nos do mal", pedimos a Deus que nos guarde de ser tentados ao pecado ou que, se tentados, nos ajude e defenda; de sorte que sejamos mantidos a salvo de cair em tentação, e que, se caídos, sejamos restaurados.', ARRAY['Oração do Senhor','tentação','perseverança'], ARRAY['Salmo 19.13','1 Coríntios 10.13'], 105, '{"full_seed":true}'::jsonb),
    (v_doc_id, 106, '106', 'O que nos ensina a conclusão da Oração do Senhor?', 'A conclusão da Oração do Senhor ("porque teu é o reino, e o poder, e a glória, para sempre. Amém") nos ensina a retirar ânimo para orar somente de Deus e no nosso louvor a elevar a ele o reino, o poder e a glória; e em testemunho de nosso desejo e segurança para ser ouvidos, dizemos: Amém.', ARRAY['Oração do Senhor','doxologia','confiança'], ARRAY['1 Crônicas 29.11-13'], 106, '{"full_seed":true}'::jsonb),
    (v_doc_id, 107, '107', 'O que é o Amém com que se conclui a Oração do Senhor?', 'A palavra Amém ao final da Oração do Senhor significa nosso desejo ardente e confiança de ser ouvidos; e para essa finalidade dizemos Amém.', ARRAY['Oração do Senhor','amém','confiança'], ARRAY['1 Coríntios 14.16','Apocalipse 22.20'], 107, '{"full_seed":true}'::jsonb)
